import { Component, OnDestroy, OnInit } from "@angular/core";
import { Subject, Subscription } from "rxjs";
import { filter, debounceTime } from "rxjs/operators";
import { MockDataService } from "./mock-data.service";

@Component({
  selector: "app-root",
  templateUrl: "./app.component.html",
  styleUrls: ["./app.component.scss"],
})
export class AppComponent implements OnInit, OnDestroy {
  title = "courses-app";

  private searchTermByCharacters: Subject<string> = new Subject<string>();
  private subscription?: Subscription;

  constructor(private mockDataService: MockDataService) {}

  ngOnInit(): void {
    this.subscription = this.searchTermByCharacters
      .pipe(
        debounceTime(300), // Prevent API calls for rapid input changes
        filter((value: string) => value.length >= 3) // Only values with 3+ characters
      )
      .subscribe((searchTerm: string) => {
        // Call the API
        this.mockDataService.getCharacters(searchTerm).subscribe((data) => {
          console.log("Characters:", data); // Log or use data as needed
        });
      });
  }
  changeCharactersInput(inputValue: string): void {
    this.searchTermByCharacters.next(inputValue); // Emit the input value into the Subject
  }

  ngOnDestroy(): void {
    if (this.subscription) {
      this.subscription.unsubscribe(); // Prevent memory leaks
    }
  }
}
